{"research_date": "2026-09-10", "pairs": [{"pair_id": "conflict_75da76535aa05fddf2a618cc", "claim_ids": ["claim_422b9eae29dfb1f489b1b175", "claim_fad80ef1d770b9ca909779cd"], "query_ids": ["q_287"], "claims": [{"claim_id": "claim_422b9eae29dfb1f489b1b175", "quote": "Tariffs on steel and aluminum from China could hike costs for large aerospace companies like Lockheed Martin Corp., which contributes to the local manufacturing of aircraft parts that topped Georgia’s exports at $12.6 billion last year.", "url": "https://pro.stateaffairs.com/ga/politics/georgia-tariffs-cars-lockheed-china", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "Lockheed Martin Corp.", "duty_rate": "125%", "reported_policy_status": "Remaining in effect"}}, {"claim_id": "claim_fad80ef1d770b9ca909779cd", "quote": "In anticipation of the tariffs – which include a base of 10% for all goods and 25% on imported cars – consumer sentiment continued a steep drop in March, reaching its lowest levels since November 2022", "url": "https://www.csmonitor.com/Business/2025/0408/tariffs-hyundai-auto-factory-jobs-georgia", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "base of 10% for all goods and 25% on imported cars", "duty_rate": "10%"}}]}, {"pair_id": "conflict_84904b8185af95e56bcbfd37", "claim_ids": ["claim_bb5bb59ac60b68f5ce5d6f24", "claim_d0e45eae1412c47ae478e05e"], "query_ids": ["q_289"], "claims": [{"claim_id": "claim_bb5bb59ac60b68f5ce5d6f24", "quote": "Muñoz directly acknowledged that the Trump administration's tariffs are pulling forward the localization strategy. \"Tariffs are helping us accelerate our localization plans. It's a very simple matter,\" he said.", "url": "https://finance.biggo.com/news/7c816f70-187d-4f54-84d6-c8c8f26bacb6", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Trump administration's tariffs"}}, {"claim_id": "claim_d0e45eae1412c47ae478e05e", "quote": "Tariff threat casts shadow over Hyundai's plant-opening party in Bryan County. Production lines move away from EVs to hybrid vehicles as", "url": "https://thecurrentga.org/2025/03/31/tariff-threat-casts-shadow-over-hyundais-plant-opening-party-in-bryan-county", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "Hyundai", "tariff_program": "Tariff threat", "affected_product": "EVs"}}]}, {"pair_id": "conflict_77ca66c690a62c7608b1337a", "claim_ids": ["claim_88a570ccde6dea7869832eb2", "claim_bf99a7e56719a997c17ae1ce"], "query_ids": ["q_290"], "claims": [{"claim_id": "claim_88a570ccde6dea7869832eb2", "quote": "With South Korean auto tariffs having fluctuated between 15% and 25%, and the majority of Hyundai's US volume still imported from Korea, the case for accelerating domestic production and local sourcing is required.", "url": "https://www.automotivemanufacturingsolutions.com/news/hyundai-commits-to-north-american-manufacturing-scale-with-36-new-models-localised-supply-chain/2640816", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "Hyundai", "tariff_program": "South Korean auto tariffs"}}, {"claim_id": "claim_bf99a7e56719a997c17ae1ce", "quote": "The 15% tariff applied to South Korean imports is increasing the economic incentive for local production expansion.", "url": "https://finance.biggo.com/news/7c816f70-187d-4f54-84d6-c8c8f26bacb6", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "15% tariff"}}]}, {"pair_id": "conflict_744c24edadf0664d908fe9f3", "claim_ids": ["claim_b71c4cae4dd2491f2ff66da8", "claim_e97435fc7f544dbf1fa0c567"], "query_ids": ["q_290"], "claims": [{"claim_id": "claim_b71c4cae4dd2491f2ff66da8", "quote": "We visited Hyundai’s new EV Metaplant in Savannah, Georgia, just as 25% tariffs on imported vehicles were announced. Go inside the factory, hear from Kia COO Steve Center on U.S. production strategy, and get Hyundai CEO Jose Muñoz’s reaction to the latest trade news", "url": "https://www.youtube.com/watch?v=u1XBETuQbVE", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "25% tariffs on imported vehicles", "announcement_date": "29 Mar 2025"}}, {"claim_id": "claim_e97435fc7f544dbf1fa0c567", "quote": "this week the Trump Administration announced a 25% tariff on vehicles imported into the us we were there in Georgia just as the news was breaking and during a media Roundtable Hyundai Motor Company president and CEO Jose Munoz was asked directly about it", "url": "https://www.youtube.com/watch?v=u1XBETuQbVE", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"legal_authority": "Trump Administration", "duty_rate": "25%"}}]}, {"pair_id": "conflict_b838efb0eb69f03bf14d20c9", "claim_ids": ["claim_9bcfdb2f3df0c91950283408", "claim_e9df5e110291e243c53e9219"], "query_ids": ["q_291"], "claims": [{"claim_id": "claim_9bcfdb2f3df0c91950283408", "quote": "Last month, Trump ordered a 25% import tax on all steel and aluminium entering the US.", "url": "https://www.bbc.com/news/articles/cgkmvdz144vo", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "25% import tax on all steel and aluminium", "duty_rate": "25%"}}, {"claim_id": "claim_e9df5e110291e243c53e9219", "quote": "Its steel-making firm Hyundai Steel is also about to take a hit from 25% US tariffs reimposed on all foreign steel and aluminum products.", "url": "https://www.kedglobal.com/automobiles/newsView/ked202503250003", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "Hyundai Steel", "duty_rate": "25%"}}]}, {"pair_id": "conflict_3385c2ff4c26b73d3615a129", "claim_ids": ["claim_19f4f2691f2dac3aa83fc9cb", "claim_e3bb2ecd1dd8619095bf04c1"], "query_ids": ["q_292"], "claims": [{"claim_id": "claim_19f4f2691f2dac3aa83fc9cb", "quote": "this week the Trump Administration announced a 25% tariff on vehicles imported into the us we were there in Georgia just as the news was breaking", "url": "https://www.youtube.com/watch?v=u1XBETuQbVE", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "25% tariff on vehicles imported into the us", "legal_authority": "Trump Administration"}}, {"claim_id": "claim_e3bb2ecd1dd8619095bf04c1", "quote": "We visited Hyundai’s new EV Metaplant in Savannah, Georgia, just as 25% tariffs on imported vehicles were announced.", "url": "https://www.youtube.com/watch?v=u1XBETuQbVE", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "Hyundai", "facility": "Metaplant", "tariff_program": "25% tariffs on imported vehicles"}}]}, {"pair_id": "conflict_12a2a06b2c7fd008311b636a", "claim_ids": ["claim_3037a49073b144d99fa82354", "claim_6e2a687ab38ca19b0283e7e6"], "query_ids": ["q_292"], "claims": [{"claim_id": "claim_3037a49073b144d99fa82354", "quote": "Hyundai Motor Group metap Plant America or HM GMA for short when fully operational The Meta plant will produce 300,000 Hyundai Kia and Genesis EVs and hybrids each year", "url": "https://www.youtube.com/watch?v=u1XBETuQbVE", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "Hyundai Motor Group metap Plant America"}}, {"claim_id": "claim_6e2a687ab38ca19b0283e7e6", "quote": "Hyundai Motor Group Metaplant America (HMGMA) is an electric vehicle (EV) production site operated by Hyundai and located in Ellabell, Bryan County, Georgia, United States.", "url": "https://en.wikipedia.org/wiki/Hyundai_Motor_Group_Metaplant_America", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "Hyundai Motor Group", "facility": "Metaplant America"}}]}, {"pair_id": "conflict_fc58b65443e223bc3a88ea2f", "claim_ids": ["claim_22e8b1bfcdce7dde7744ad88", "claim_dfb479d42e157790c66371d0"], "query_ids": ["q_293"], "claims": [{"claim_id": "claim_22e8b1bfcdce7dde7744ad88", "quote": "Hyundai will] not have to pay any tariffs", "url": "https://www.wita.org/blogs/hyundais-investment-korea", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {}}, {"claim_id": "claim_dfb479d42e157790c66371d0", "quote": "The South Korean-based automaker is the largest U.S. importer of new vehicles from the country, followed by GM. Both automakers have paid billions of dollars in levies so far this year after President Donald Trump placed 25% tariffs on imported vehicles from South Korea and other countries in the spring.", "url": "https://www.cnbc.com/2025/12/03/trump-south-korea-tariffs-vehicles-hyundai-gm.html", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"exporting_country": "South Korea", "duty_rate": "25%", "effective_date": "spring"}}]}, {"pair_id": "conflict_e54b7edc49d2978cbd1fbb5e", "claim_ids": ["claim_3943b55a03a42bce91511100", "claim_dfb479d42e157790c66371d0"], "query_ids": ["q_293"], "claims": [{"claim_id": "claim_3943b55a03a42bce91511100", "quote": "The Trump administration this past week confirmed plans to lower tariffs on certain products, including vehicles, to 15% from South Korea. A notice about the implementation of the trade deal was posted Wednesday on the Federal Register.", "url": "https://www.cnbc.com/2025/12/03/trump-south-korea-tariffs-vehicles-hyundai-gm.html", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "lower tariffs", "duty_rate": "15%"}}, {"claim_id": "claim_dfb479d42e157790c66371d0", "quote": "The South Korean-based automaker is the largest U.S. importer of new vehicles from the country, followed by GM. Both automakers have paid billions of dollars in levies so far this year after President Donald Trump placed 25% tariffs on imported vehicles from South Korea and other countries in the spring.", "url": "https://www.cnbc.com/2025/12/03/trump-south-korea-tariffs-vehicles-hyundai-gm.html", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"exporting_country": "South Korea", "duty_rate": "25%", "effective_date": "spring"}}]}, {"pair_id": "conflict_fe85458cbc7fc834657eb720", "claim_ids": ["claim_0f7c77129786fba1bc07d1db", "claim_f220f942c7976b8b947afe61"], "query_ids": ["q_295"], "claims": [{"claim_id": "claim_0f7c77129786fba1bc07d1db", "quote": "Hyundai and sister brand Kia have paid almost 5 million won ($3,600) as tariff per vehicle exported in the second quarter", "url": "https://www.koreajoongangdaily.com/business/hyundai-in-a-catch-22-as-it-absorbs-us-tariffs-while-toyota-volkswagen-benefit-from-deals/12005889", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "Kia", "duty_rate": "almost 5 million won ($3,600) as tariff per vehicle"}}, {"claim_id": "claim_f220f942c7976b8b947afe61", "quote": "Hyundai Motor is bearing mounting costs on an unprecedented scale due to the hefty 25 percent tariff imposed by the Donald Trump administration", "url": "https://www.koreajoongangdaily.com/business/hyundai-in-a-catch-22-as-it-absorbs-us-tariffs-while-toyota-volkswagen-benefit-from-deals/12005889", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "Hyundai Motor", "tariff_program": "hefty 25 percent tariff imposed by the Donald Trump administration", "duty_rate": "25 percent"}}]}]}

